oxy_webhelp_navlinks = {"evaluate_options_gcp_storage_tiering-d39307e20874":{"topics":[{"title":"GCS storage classes","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports four GCS storage classes when creating an archival         location to meet different storage requirements.<\/p>","href":"gcp\/gcs_storage_classes_2.html","attributes":{"data-id":"gcs_storage_classes"},"menu":{"hasChildren":false},"tocID":"gcs_storage_classes-d39307e20885","topics":[]},{"title":"GCP instant tiering","shortdesc":"<p class=\"shortdesc\">In <span class=\"ph\">RSC<\/span>, you can instantly tier GCE instance or persistent disk         snapshots to the specified archival location, enhancing cost efficiency.<\/p>","href":"gcp\/gcp_instant_tiering.html","attributes":{"data-id":"gcp_instant_tiering"},"menu":{"hasChildren":false},"tocID":"gcp_instant_tiering-d39307e20898","topics":[]},{"title":"Custom storage encryption for GCP","shortdesc":"<p class=\"shortdesc\">When creating a GCP archival location in <span class=\"ph\">RSC<\/span>, you can use custom         storage encryption to encrypt the archived data using Customer-managed encryption         keys.<\/p>","href":"gcp\/custom_strg_encryption_gcp.html","attributes":{"data-id":"custom_strg_encryption_gcp"},"menu":{"hasChildren":false},"tocID":"custom_strg_encryption_gcp-d39307e20912","topics":[]},{"title":"Private bucket network access for GCP storage tiering","shortdesc":"<p class=\"shortdesc\">When creating a Google Cloud Platform archival location, you can restrict bucket         access to Exocompute Virtual Private Cloud networks only, preventing <span class=\"ph\">RSC<\/span>         deployment IP addresses from accessing the Google Cloud Storage bucket directly.<\/p>","href":"gcp\/gcp_private_bucket_network_access.html","attributes":{"data-id":"gcp_private_bucket_network_access"},"menu":{"hasChildren":false},"tocID":"gcp_private_bucket_network_access-d39307e20926","topics":[]},{"title":"Encryption options for GCP cloud-native archival","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports three encryption options for GCP cloud-native archival         locations: client-side encryption using your Google Cloud KMS key, server-side encryption         using a customer-managed key, and server-side encryption using a platform-managed         key.<\/p>","href":"gcp\/gcp_cnp_archival_encryption_options.html","attributes":{"data-id":"gcp_cnp_archival_encryption_options"},"menu":{"hasChildren":false},"tocID":"gcp_cnp_archival_encryption_options-d39307e20940","topics":[]},{"title":"Client-side encryption for GCP cloud-native archival","shortdesc":"<p class=\"shortdesc\">Client-side encryption encrypts archived Google Compute Engine instance and         persistent disk data using your Google Cloud Key Management Service key before the data         leaves the Exocompute environment.<\/p>","href":"gcp\/gcp_cnp_client_side_encryption.html","attributes":{"data-id":"gcp_cnp_client_side_encryption"},"menu":{"hasChildren":false},"tocID":"gcp_cnp_client_side_encryption-d39307e20953","topics":[]}]}};